test("90 度回った親から回っていない親へ付け替えると、中心が同じ位置に来る座標が書かれる", () => {
  /*
   * 運んだ先 (10, 17) の左上は落とし先の座標で (233, 10)。中心 (20, 23) は (227, 20) に
   * 写るので、そこから大きさの半分を戻した (217, 14)。左上を保つと中心が (243, 16) へ跳ぶ
   */
  const dropped = RepositionTarget.create(
    GrabbedInTurned,
    { x: -7, y: 0 },
    Home,
  );

  expect(dropped.written.to).toEqual({
    parentName: "home",
    placement: { mode: "absolute", x: 217, y: 14 },
  });
});

test("90 度回った親から回っていない親へ付け替えると、自分の向きが差の 90 度になる", () => {
  const dropped = RepositionTarget.create(
    GrabbedInTurned,
    { x: -7, y: 0 },
    Home,
  );

  expect(dropped.written.rotation).toEqual(Option.some(90));
});

test("回っていない親から 90 度回った親へ付け替えると、中心が同じ位置に来る座標が書かれる", () => {
  // 左上を落とし先の向きで測った (30, 50) から、中心を保つ分 (-4, -16) だけ直す
  const dropped = RepositionTarget.create(
    GrabbedInHome,
    { x: 180, y: -120 },
    Frame,
  );

  expect(dropped.written.to).toEqual({
    parentName: "frame",
    placement: { mode: "absolute", x: 26, y: 34 },
  });
});

test("回っていない親から 90 度回った親へ付け替えると、自分の向きが差の -90 度になる", () => {
  const dropped = RepositionTarget.create(
    GrabbedInHome,
    { x: 180, y: -120 },
    Frame,
  );

  expect(dropped.written.rotation).toEqual(Option.some(-90));
});

test("自分が回っていれば、書かれる向きは自分の向きに差を足した値になる", () => {
  expect(
    writtenRotation({ parentRotation: 90, dropRotation: 0, ownRotation: 30 }),
  ).toEqual(Option.some(120));
});

test("自分の向きに差を足して 1 回りになっても、1 回りに収め直さずに書かれる", () => {
  expect(
    writtenRotation({ parentRotation: 90, dropRotation: 0, ownRotation: 270 }),
  ).toEqual(Option.some(360));
});

test("同じ親の中で動かすときは、向きを書かない", () => {
  const dropped = RepositionTarget.create(
    GrabbedInTurned,
    { x: -7, y: 0 },
    {
      name: "frame",
      shift: { x: 0, y: 0 },
      rotation: 90,
    },
  );

  expect(dropped.written.rotation).toEqual(Option.none);
});

test("360 度回った親から回っていない親へ付け替えると、左上を保った座標が書かれる", () => {
  const dropped = RepositionTarget.create(
    {
      ...GrabbedInHome,
      placement: { mode: "absolute", x: 40, y: 24 },
      parentRotation: 360,
    },
    { x: 30, y: -12 },
    { name: "home", shift: { x: 0, y: 0 }, rotation: 0 },
  );

  expect(dropped.written.to.placement).toEqual({
    mode: "absolute",
    x: 70,
    y: 12,
  });
});

test("大きさの半分が整数でなくても、付け替えで書かれる座標は整数になる", () => {
  // 21x12 なら中心を保つ分は (-16.5, 4.5) で、丸めないと (216.5, 14.5) の端数が書かれる
  const dropped = RepositionTarget.create(
    { ...GrabbedInTurned, centerFromTopLeft: { x: 10.5, y: 6 } },
    { x: -7, y: 0 },
    Home,
  );

  expect(dropped.written.to.placement).toEqual({
    mode: "absolute",
    x: 217,
    y: 15,
  });
});

test("向きの違う親へ付け替えても、画面上の中心は運んでいる間の位置から 0.71px 以内に来る", () => {
  // 座標を整数へ丸めるので縦横それぞれ 0.5px まではずれる。中心を直さないと 8px 以上跳ぶ
  const { centerGap } = centersAndOrientations(...ThirtyToSeventyFive);

  expect(centerGap).toBeLessThanOrEqual(Math.SQRT1_2);
});

test("向きの違う親へ付け替えても、画面上の向きは運んでいる間と同じ", () => {
  const { carriedOrientation, droppedOrientation } = centersAndOrientations(
    ...ThirtyToSeventyFive,
  );

  expect(droppedOrientation).toBe(carriedOrientation);
});

test("0.1 度の中の 0.2 度の親から 0.3 度の親へ付け替えても、向きを書かない", () => {
  expect(
    writtenRotation({
      parentRotation: 0.1 + 0.2,
      dropRotation: 0.3,
      ownRotation: 0,
    }),
  ).toEqual(Option.none);
});

test("0.1 度回ったノードを 0.2 度の差の親へ付け替えると、端数の無い和が書かれる", () => {
  expect(
    writtenRotation({ parentRotation: 0.2, dropRotation: 0, ownRotation: 0.1 }),
  ).toEqual(Option.some(0.3));
});

test("90 度回った Box の中から回っていない親へ付け替えると、画面上の向きと中心を保つ向きと座標が書かれる", () => {
  /*
   * `frame` の座標の原点（回って描かれた左上の角）は `home` の座標で (250, 0)。運んだ先
   * (10, 17) を `home` の向きへ回すと (-17, 10) で、原点の位置を足して (233, 10)。自分の向きを
   * 90 度にすると中心が左上のまわりに回るので、20x12 の中心を保つ分 (-16, 4) だけ直して (217, 14)
   */
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: turnedFrameSelection(90), onRepositionNode });
  drawnTurnedFrame();

  dragNodeOnto("chip", drawn("home"), { x: -7, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith(
    "chip",
    RepositionEdit.rotatedTo(
      {
        parentName: "home",
        placement: { mode: "absolute", x: 217, y: 14 },
      },
      90,
    ),
  );
});

test("90 度回った Box の中の 30 度回ったノードを回っていない親へ付け替えると、向きは差を足した 120 度になる", () => {
  /*
   * 中心 (334, 80) のまま画面上で 120 度に立っている。回る前の大きさは同じなので、書かれる
   * 座標は回っていないノードと同じ (217, 14)
   */
  const onRepositionNode = vi.fn();
  renderCanvas({
    selection: turnedFrameSelection(90, { rotation: 30 }),
    onRepositionNode,
  });
  drawnTurnedFrame();
  drawnTurnedAt(
    "chip",
    { left: 323.804, top: 68.34, width: 20.392, height: 23.32 },
    { width: 20, height: 12 },
  );

  dragNodeOnto("chip", drawn("home"), { x: -7, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith(
    "chip",
    RepositionEdit.rotatedTo(
      {
        parentName: "home",
        placement: { mode: "absolute", x: 217, y: 14 },
      },
      120,
    ),
  );
});

test("倍率を上げても、90 度回った Box の中から回っていない親へ付け替えると、画面上の向きと中心を保つ向きと座標が書かれる", () => {
  /*
   * 1.2 倍で画面上の左へ 8.4 運ぶと、倍率で割り戻して 7 になり、1 倍で 7 運んだときと同じ
   * (217, 14) になる。中心も倍率で割り戻さないと、座標がずれて書かれる
   */
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: turnedFrameSelection(90), onRepositionNode });
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");
  drawnAt("home", { left: 100, top: 60, width: 432, height: 288 });
  drawnTurnedAt(
    "frame",
    { left: 280, top: 60, width: 120, height: 240 },
    { width: 200, height: 100 },
  );
  drawnTurnedAt(
    "chip",
    { left: 373.6, top: 72, width: 14.4, height: 24 },
    { width: 20, height: 12 },
  );

  dragNodeOnto("chip", drawn("home"), { x: -8.4, y: 0 });

  expect(onRepositionNode).toHaveBeenCalledWith(
    "chip",
    RepositionEdit.rotatedTo(
      {
        parentName: "home",
        placement: { mode: "absolute", x: 217, y: 14 },
      },
      90,
    ),
  );
});

test("360 度回った Box の中から回っていない親へ付け替えても、向きは書かれない", () => {
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: turnedFrameSelection(360), onRepositionNode });
  drawnUprightFrame();

  dragNodeOnto("chip", drawn("home"), { x: 12, y: 5 });

  // 付け替えは起きる（`home` を指す）が、向きの差が 1 回りなので左上を保って向きは書かない
  expect(onRepositionNode).toHaveBeenCalledWith(
    "chip",
    RepositionEdit.create({
      parentName: "home",
      placement: { mode: "absolute", x: 122, y: 65 },
    }),
  );
});

test("別の親へ向きを指して置き直すと、その向きが書かれる", () => {
  const props = repositionRotatedBadge(
    30,
    RepositionEdit.rotatedTo(
      ChildPlacement.create("panel", { mode: "absolute", x: 52, y: 19 }),
      120,
    ),
  );

  expect(props.rotation).toBe(120);
});

test("別の親へ回っていない向きを指して置き直すと、向きは未設定に戻る", () => {
  const props = repositionRotatedBadge(
    45,
    RepositionEdit.rotatedTo(
      ChildPlacement.create("panel", { mode: "absolute", x: 52, y: 19 }),
      0,
    ),
  );

  expect("rotation" in props).toBe(false);
});

test("別の親へ向きを指さずに置き直すと、数値でない向きもそのまま残る", () => {
  const props = repositionRotatedBadge(
    "abc",
    RepositionEdit.create(
      ChildPlacement.create("panel", { mode: "absolute", x: 52, y: 19 }),
    ),
  );

  expect(props.rotation).toBe("abc");
});

test("同じ親の中で向きを指して置き直しても、その向きが書かれる", () => {
  const props = repositionRotatedBadge(
    30,
    RepositionEdit.rotatedTo(
      ChildPlacement.create("home", { mode: "absolute", x: 52, y: 19 }),
      120,
    ),
  );

  expect(props.rotation).toBe(120);
});

test("向きも書き換えて親をまたいだ置き直しは、1 回戻すと親・座標・向きが全部戻る", () => {
  const repositioned = Option.unwrap(
    EditorState.reposition(
      setupState({ rotation: 30 }),
      "badge",
      RepositionEdit.rotatedTo(
        ChildPlacement.create("panel", { mode: "absolute", x: 8, y: 6 }),
        120,
      ),
    ),
  );

  const undone = Option.unwrap(EditorState.undo(repositioned));

  expect([
    badgeParentName(undone),
    badgeProps(undone).x,
    badgeProps(undone).rotation,
  ]).toEqual(["home", 40, 30]);
});

test("数値でない向きを書いたノードを動かしても、その綴りが残る", () => {
  // 読み直して書くと、数値でない綴りは回っていない向き（0）として読まれて消える
  const selected = EditorState.select(setupState({ rotation: "abc" }), "badge");

  const moved = EditorState.repositionSelectedNodeBy(selected, { x: 1, y: 0 });

  expect(badgeProps(Option.unwrap(moved)).rotation).toBe("abc");
});

test("向きの足し引きで出た端数は丸めると落ちる", () => {
  expect(Angle.roundToMicrodegree(0.1 + 0.2)).toBe(0.3);
});

test("小数点以下 6 桁までの角度は丸めても変わらない", () => {
  expect(Angle.roundToMicrodegree(12.345678)).toBe(12.345678);
});

test("回っていない角度を書くと向きは未設定に戻る", () => {
  expect(Props.apply({ rotation: 30 }, Rotation.toPropEdit(0))).toEqual({});
});

test("大きさが奇数でも、回る前の左上から中心までの差は大きさのちょうど半分になる", () => {
  const bounds = {
    unrotated: { left: 100, top: 50, width: 21, height: 13 },
    rotation: 30,
  };

  expect(RotatedBounds.centerFromTopLeft(bounds)).toEqual({ x: 10.5, y: 6.5 });
});

test("90 度回った Box の中のノードを回っていない artboard へ運ぶと、中心を保つ位置に 90 度回って描かれる", async () => {
  await renderOpenedDocument(turnedFrameDocument(90));
  // キャンバスで押すと外側の `frame` が掴まれるので、ツリーで `chip` を選んでから運ぶ
  await userEvent.click(screen.getByRole("button", { name: "chip" }));
  drawnTurnedFrame();

  pressPointer(drawn("chip"), { x: 100, y: 100 });
  movePointer(drawn("home"), { x: 93, y: 100 });
  releasePointer(drawn("home"), { x: 93, y: 100 });

  const moved = drawn("chip");
  expect([moved.style.left, moved.style.top, moved.style.transform]).toEqual([
    "217px",
    "14px",
    "rotate(90deg)",
  ]);
});

export type GrabbedPlacement = Readonly<{
  placement: AbsolutePlacement;
  parentRotation: Angle;
}>;

/**
 * 掴んだ時点の配置に、向きの違う親へ付け替えるときに見た目を保つための自分の形を足したもの。
 *
 * 付け替えで自分の向きを書き換えると、回る中心（回る前の矩形の中心）の位置が座標の原点
 * （回る前の左上）から見て向きの差だけ回る。中心を動かさないよう座標を直すには、自分の向きと
 * 左上から中心までの差が要る。
 */
export type GrabbedGeometry = GrabbedPlacement &
  Readonly<{
    /** 自分の `rotation`（今の親の向きを基準にした角度）。 */
    ownRotation: Angle;
    /** 回る前の左上の角から中心までの差（ドキュメント上の px）。 */
    centerFromTopLeft: Offset;
  }>;

export type RepositionEdit = Readonly<{
  /** 置き直したあとの親と、その親から見た座標。 */
  to: ChildPlacement;
  /** 書き込む自分の向き。向きを書き換えないなら `none`。 */
  rotation: Option<Angle>;
}>;

export const RepositionEdit = {
  /**
   * 向きを書き換えない置き直し。同じ親の中で動かすときと、向きの差が 1 回りの倍数の親へ
   * 付け替えるときの形。
   *
   * @param to 置き直したあとの親と座標
   * @returns 親と座標だけを書き込む編集
   */
  create(to: ChildPlacement): RepositionEdit {
    return { to, rotation: Option.none };
  },

  /**
   * 向きも書き換える置き直し。向きの違う親へ付け替えるときの形。
   *
   * @param to 置き直したあとの親と座標
   * @param rotation 置き直したあとの自分の向き（新しい親の向きを基準にした角度）
   * @returns 親と座標と向きを書き込む編集
   */
  rotatedTo(to: ChildPlacement, rotation: Angle): RepositionEdit {
    return { to, rotation: Option.some(rotation) };
  },
} as const;

create(
  from: GrabbedGeometry,
  carried: Offset,
  dropParent: DropParentCoordinates,
): RepositionTarget {
  const moved = movedInParent(from, carried);
  const rotationGap = Angle.roundToMicrodegree(
    from.parentRotation - dropParent.rotation,
  );
  const center = Offset.add(Placement.offset(moved), from.centerFromTopLeft);
  // 向きの差が 360 度の倍数なら `Offset.rotate` が元と同じ値を返すので、左上を保つ
  const to = ChildPlacement.create(
    dropParent.name,
    Placement.moveBy(
      moved,
      Offset.add(
        Offset.delta(center, Offset.rotate(center, rotationGap)),
        dropParent.shift,
      ),
    ),
  );
  return {
    written: Angle.isWholeTurns(rotationGap)
      ? RepositionEdit.create(to)
      : RepositionEdit.rotatedTo(
          to,
          Angle.roundToMicrodegree(from.ownRotation + rotationGap),
        ),
    offset: offsetToward(from, moved),
  };
},
